solutions.cpp:
#include <optional>
#include <vector>
using namespace std;

optional<int> secondLargest(const vector<int>& nums) {
    optional<int> largest;
    optional<int> second;

    for (int value : nums) {
        if (!largest || value > *largest) {
            second = largest;
            largest = value;
        } else if (value < *largest && (!second || value > *second)) {
            second = value;
        }
    }
    return second;
}

json solve(const json& input) {
    const auto nums = input.get<vector<int>>();
    const auto answer = secondLargest(nums);
    return answer ? json(*answer) : json(nullptr);
}

