        while st:
            x,y=st.pop();size+=1
            for xx,yy in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                if 0<=xx<n and 0<=yy<n and a[xx][yy]==1:a[xx][yy]=label;st.append((xx,yy))
