int cap=input.at("capacity").get<int>();list<pair<int,int>>l;unordered_map<int,list<pair<int,int>>::iterator>m;json out=json::array();for(auto op:input.at("operations")){string cmd=op[0].get<string>();int k=op[1].get<int>();auto it=m.find(k);if(cmd=="get"){if(it==m.end())out.push_back(-1);else{l.splice(l.end(),l,it->second);out.push_back(it->second->second);}}else{if(it!=m.end()){l.erase(it->second);m.erase(it);}l.push_back({k,op[2].get<int>()});m[k]=prev(l.end());if((int)m.size()>cap){m.erase(l.front().first);l.pop_front();}out.push_back(nullptr);}}return out;
}

